mapper.select:
SELECT id, content, updated_at
FROM course_comments
WHERE source_language = 'und'
  AND id > #{afterId}
ORDER BY id
LIMIT #{limit}

mapper.insert:
INSERT INTO course_comments (
    parent_comment_id, reply_to_comment_id, content, source_language, deleted,
    create_at, updated_at, user_id, course_id
) VALUES (
    #{parentCommentId}, #{replyToCommentId}, #{content}, #{sourceLanguage}, 0,
    NOW(), NOW(), #{userId}, #{courseId}
)

mapper.update:
UPDATE course_comments
SET deleted = 1,
    deleted_at = NOW()
WHERE id = #{commentId}
  AND user_id = #{userId}
  AND deleted = 0

mapper.delete:
DELETE FROM course_comment_likes
WHERE user_id = #{userId}
  AND comment_id = #{commentId}
